const plans=window.SIMNOTE_DATA;
const countries=[{id:'US',name:'美国',dial:'+1'},{id:'UK',name:'英国',dial:'+44'},{id:'HK',name:'中国香港',dial:'+852'},{id:'JP',name:'日本',dial:'+81'},{id:'SG',name:'新加坡',dial:'+65'},{id:'FR',name:'法国',dial:'+33'},{id:'DE',name:'德国',dial:'+49'},{id:'ES',name:'西班牙',dial:'+34'},{id:'AU',name:'澳大利亚',dial:'+61'},{id:'CA',name:'加拿大',dial:'+1'}];
const state={layout:'cards',view:'plans',region:'all',condition:'all',query:'',selected:new Set()};
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>',sim:'<path d="M8 3h7l4 4v14H5V6a3 3 0 0 1 3-3Z"/><rect x="8" y="10" width="8" height="7" rx="1"/><path d="M12 10v7m-4-3.5h8"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',id:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="8" cy="10" r="2"/><path d="M5 16c0-4 6-4 6 0m3-7h4m-4 4h4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2l-1.5 1v1m0 3h.01"/>',book:'<path d="M12 5v15M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2V4Z"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>','arrow-up':'<path d="M6 18 18 6M6 6h12v12"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5m-4 8a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',sliders:'<path d="M4 7h4m4 0h8M4 17h9m4 0h3"/><circle cx="10" cy="7" r="2"/><circle cx="15" cy="17" r="2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wallet:'<path d="M20 7V4H6a3 3 0 0 0 0 6h15v10H6a3 3 0 0 1-3-3V7m18 6h-5v4h5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.info}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.outerHTML=icon(el.dataset.icon)})}
function logo(p,button=true){return button?`<button class="provider-logo logo-${p.id}" data-detail="${p.id}" aria-label="查看 ${p.name} 详情与官方 FAQ" title="查看 ${p.name} 详情">${p.mark}</button>`:`<span class="provider-logo logo-${p.id}" aria-hidden="true">${p.mark}</span>`}
function provider(p){return `<div class="provider-cell">${logo(p)}<div><button class="provider-name text-reset" data-detail="${p.id}">${p.name}</button><div class="provider-meta">${p.place} <span>· ${p.dial}</span></div><span class="provider-tag">${p.plan}</span></div></div>`}
function price(p){const symbol=({GBP:'£',EUR:'€',JPY:'¥'})[p.currency]||'$';return `<div class="price"><small class="currency">${p.currency}</small>${symbol}${p.price}<span>/ ${p.unit}</span></div><div class="price-note">${p.priceNote}</div>`}
function help(p,kind){return `<button class="help-button" data-detail="${p.id}" data-focus="${kind}" aria-label="查看 ${p.name} ${kind==='cost'?'费用说明':kind==='registration'?'注册条件':'短信条件'}" title="点击查看官网说明">${icon('help')}</button>`}
function sourceLink(p,index,label){const s=p.source[index];return `<a class="source-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${label||esc(s.title)} ${icon('arrow-up')}</a>`}
const countryAliases={US:'United States USA America 美国',UK:'United Kingdom Britain England 英国',HK:'Hong Kong 香港',JP:'Japan 日本',SG:'Singapore 新加坡',FR:'France 法国',DE:'Germany Deutschland 德国',ES:'Spain España 西班牙',AU:'Australia 澳洲 澳大利亚',CA:'Canada 加拿大'};
function searchable(p){return [p.name,p.place,p.dial,countryAliases[p.region],p.plan,p.currency,p.cost,p.kycLabel,p.activation,p.documents,p.setup,p.warning,p.sms,p.keep,...p.faqs.flatMap(f=>[f.q,f.a,f.topic])].join(' ').toLowerCase()}
function filtered(){return plans.filter(p=>(state.region==='all'||state.region===p.region)&&(state.condition==='all'||state.condition===p.kyc)&&searchable(p).includes(state.query.trim().toLowerCase()))}
function empty(){return `<div class="empty-state">${icon('search')}<h3>没有找到匹配的${state.view==='faq'?'问题':'方案'}</h3><p>试试“短信”“保号”“美国”，或清除筛选条件。</p><button id="reset-filters">清除搜索与筛选</button></div>`}
function row(p){return `<article class="plan-row ${state.selected.has(p.id)?'selected':''}" aria-label="${p.name} 保号方案">${provider(p)}<div class="price-cell">${price(p)}${help(p,'cost')}</div><div class="condition-cell"><span class="cell-mobile-label">注册与开通</span><span class="badge ${p.id==='tello'||p.id==='usmobile'?'warning':''}">${p.activation}</span><div class="cell-note">${p.kycLabel} ${help(p,'registration')}</div></div><div class="sms-cell"><span class="cell-mobile-label">号码与短信</span><div class="cell-title">${p.sms}${help(p,'sms')}</div><div class="cell-note">${p.smsNote}</div></div><div class="plan-actions"><label class="compare-choice"><input type="checkbox" data-compare="${p.id}" ${state.selected.has(p.id)?'checked':''} aria-label="选择 ${p.name} 加入对比">${state.selected.has(p.id)?'已加入':'对比'}</label><button class="detail-link" data-detail="${p.id}">查看详情 ${icon('arrow')}</button></div></article>`}
function card(p){return `<article class="plan-card ${state.selected.has(p.id)?'selected':''}" aria-label="${p.name} 保号方案"><div class="card-top">${provider(p)}<label class="card-compare" title="选择加入对比"><input type="checkbox" data-compare="${p.id}" ${state.selected.has(p.id)?'checked':''} aria-label="选择 ${p.name} 加入对比"><span>${state.selected.has(p.id)?'已选':'对比'}</span></label></div><div class="card-cost"><div>${price(p)}</div>${help(p,'cost')}</div><div class="card-category ${p.mode==='parked'?'parked':''}"><span>${p.priceType}</span><span>${p.mode==='parked'?'暂时停用 · 保留号码':'eSIM · 手机号码'}</span></div><dl class="card-facts"><div><dt>${icon('id')} 实名条件</dt><dd>${p.kycLabel}${help(p,'registration')}</dd></div><div><dt>${icon('globe')} 首次开通</dt><dd>${p.activation}</dd></div><div><dt>${icon('sim')} 短信服务</dt><dd>${p.sms}${help(p,'sms')}</dd></div></dl><div class="card-bottom"><span>${p.faqs.length} 条官方 FAQ</span><button data-detail="${p.id}">查看详情 ${icon('arrow')}</button></div></article>`}
function renderPlans(items){if(state.layout==='cards')return '<div class="plan-grid">'+items.map(card).join('')+'</div>';return `<div class="plan-table"><div class="table-head" aria-hidden="true"><span>运营商 / 号码</span><span>参考费用</span><span>注册与开通条件</span><span>号码与短信</span><span>加入对比</span></div>${items.map(row).join('')}</div>`}
function facts(p){return `<dl class="detail-facts"><div><dt>实名要求</dt><dd>${p.documents}</dd></div><div><dt>开通地区</dt><dd>${p.setup}</dd></div><div><dt>保号规则</dt><dd>${p.keep}</dd></div></dl>`}
function renderRequirements(items){return `<div class="requirements-grid">${items.map(p=>`<article class="requirement-card"><div class="detail-brand">${logo(p)}<div><h2>${p.name}</h2><p>${p.place} ${p.dial}</p></div></div><span class="badge ${p.kyc==='required'?'warning':''}">${p.kycLabel}</span>${facts(p)}<button class="detail-link" data-detail="${p.id}" data-focus="registration">展开条件与官网出处 ${icon('arrow')}</button></article>`).join('')}</div>`}
function faqMarkup(p,f,opened=false){return `<details class="faq-item" id="${f.id}" ${opened?'open':''}><summary>${esc(f.q)}</summary><div class="faq-answer"><p>${esc(f.a)}</p>${sourceLink(p,f.source,'查看官方原文')}</div></details>`}
function matchingFaqs(p){const q=state.query.trim().toLowerCase();if(!q||[p.name,p.place,p.dial,countryAliases[p.region]].join(' ').toLowerCase().includes(q))return p.faqs;return p.faqs.filter(f=>[f.q,f.a,f.topic].join(' ').toLowerCase().includes(q))}
function renderFaq(items){const groups=items.map(p=>({p,faqs:matchingFaqs(p)})).filter(g=>g.faqs.length);return groups.length?groups.map(({p,faqs})=>`<section class="faq-group"><h3 class="faq-group-heading">${logo(p)}${p.name}<span>${faqs.length} 个问题</span></h3><div class="faq-list">${faqs.map(f=>faqMarkup(p,f)).join('')}</div></section>`).join(''):empty()}
function renderSources(items){return `<div class="methodology"><h3>我们怎样比较？</h3><ul><li>只收录提供手机号的 eSIM 方案；未将纯旅行流量 eSIM 列为保号卡。</li><li>金额保留各地原始币种；不按币种面值混排，也不使用未经核实的汇率。</li><li>年付、30 天套餐、新卡费、可消费充值余额分别注明。休眠保号单独标注，不等同于正常通信服务。</li><li>“官网未列证件实名”表示查阅页面未明确，不是“免实名”或一定能开户的保证。</li><li>资料核对：2026-09-13。仅为人工整理的静态快照，实际费用与条件以官网为准。</li></ul></div>${items.map(p=>`<article class="source-card"><h3>${p.name} <span class="badge">官方网站</span></h3><p>${p.source.length} 个来源 · 核对日期 2026-09-13</p><div class="official-links">${p.source.map((s,i)=>sourceLink(p,i)).join('')}</div></article>`).join('')}`}
function render(){$('#layout-switch').hidden=state.view!=='plans';$('#new-arrivals').hidden=state.view!=='plans';document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.layout===state.layout));$('#country-select').value=state.region;document.querySelectorAll('[data-region]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.region===state.region));const items=filtered();const titles={plans:['方案对比','选一个，长期在线的号码。','跨 10 个国家和地区，对比费用、实名要求与长期使用条件。','长期保号方案','选择 2–3 个方案，展开并排对比'],requirements:['注册条件','开通之前，把条件看清楚。','实名、激活地区与保号要求，分别核对。','开通条件速查','点击运营商图标，查看官网说明'],faq:['FAQ 资料库','你关心的问题，官网怎么说？','搜索费用、实名、激活与短信问题，展开查看官方出处。','官方 FAQ 资料库','中文摘要 · 点击问题展开'],sources:['资料来源','每条信息，都有出处。','直接查阅运营商的定价与帮助页面。','官网来源','人工整理 · 非实时报价']};const t=titles[state.view];$('#breadcrumb-current').textContent=t[0];$('#page-title').innerHTML=esc(t[1].slice(0,-1))+'<span>。</span>';$('#page-description').textContent=t[2];$('#results-heading').innerHTML=t[3]+' <span id="result-count"></span>';$('#result-count').textContent=state.view==='faq'?items.reduce((n,p)=>n+matchingFaqs(p).length,0):items.length;$('#result-hint').textContent=t[4];document.querySelectorAll('[data-view]').forEach(a=>{const active=a.dataset.view===state.view;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===state.region);b.setAttribute('aria-pressed',b.dataset.filter===state.region)});$('#quick-faq').hidden=state.view!=='plans';$('#results').innerHTML=items.length?({plans:renderPlans,requirements:renderRequirements,faq:renderFaq,sources:renderSources}[state.view])(items):empty();renderCompareBar()}
function renderCompareBar(){const n=state.selected.size;$('#compare-bar').hidden=!n;$('#selected-count').textContent=n;$('#selected-brands').innerHTML=plans.filter(p=>state.selected.has(p.id)).map(p=>logo(p,false)).join('');$('#open-compare').disabled=n<2;$('#open-compare').title=n<2?'至少选择两个方案':'并排查看所选方案'}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,3000)}
function toggleCompare(id,checked){if(checked&&state.selected.size>=3){toast('最多同时对比 3 个方案，请先移除一个。');render();return}checked?state.selected.add(id):state.selected.delete(id);render()}
function openDetail(id,focus){const p=plans.find(p=>p.id===id);if(!p)return;$('#detail-content').innerHTML=`<div class="eyebrow">PROVIDER NOTE / ${p.region}</div><div class="detail-brand">${logo(p,false)}<div><h2 id="detail-title">${p.name}</h2><p>${p.place} ${p.dial} · ${p.plan}</p></div></div><p class="detail-intro">${p.intro}</p><div class="detail-price" id="detail-cost">${price(p)}<p class="price-note">${p.cost}</p></div><h3 class="detail-section-title" id="detail-registration">注册与保号</h3>${facts(p)}<div class="detail-warning">${icon('info')}<span>${p.warning}</span></div><h3 class="detail-section-title" id="detail-sms">官方 FAQ <span class="badge">${p.faqs.length} 个问题</span></h3>${p.faqs.map(f=>faqMarkup(p,f,f.id===focus)).join('')}<h3 class="detail-section-title">官网资料来源</h3><div class="official-links">${p.source.map((s,i)=>sourceLink(p,i)).join('')}</div><div class="detail-footer"><span>资料核对 2026.09.13 · 中文整理</span>${sourceLink(p,0,'前往官网')}</div>`;const dialog=$('#detail-dialog');dialog.showModal();dialog.scrollTop=0;if(focus){requestAnimationFrame(()=>{const target=dialog.querySelector('[id="'+focus+'"]')||dialog.querySelector('#detail-'+focus);if(target)target.scrollIntoView({block:'start'})})}}
function openCompare(){const items=plans.filter(p=>state.selected.has(p.id));if(items.length<2)return;const rows=[['参考费用',p=>price(p)],['费用口径',p=>p.cost],['号码归属',p=>`${p.place} ${p.dial}`],['实名条件',p=>p.documents],['开通地区',p=>p.setup],['保号类型',p=>p.mode==='parked'?'休眠保号：暂时停用后恢复':p.priceType],['保号要求',p=>p.keep],['短信与漫游',p=>p.sms+'。'+p.smsNote],['特别留意',p=>p.warning],['官网资料',p=>p.source.map((s,i)=>sourceLink(p,i)).join('<br>')]];$('#compare-content').innerHTML=`<div class="eyebrow">SIDE BY SIDE</div><h2 id="compare-title">把 ${items.length} 个方案，放在一起看。</h2><p class="detail-intro">价格保留原币种，注意充值余额与套餐费的区别。</p><div class="comparison-scroll" tabindex="0" role="region" aria-label="方案对比表，可横向滚动"><table class="comparison-table"><thead><tr><th scope="col">比较项目</th>${items.map(p=>`<th scope="col"><div class="provider-cell">${logo(p,false)}${p.name}</div></th>`).join('')}</tr></thead><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${label}</th>${items.map(p=>`<td>${value(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('#compare-dialog').showModal()}
document.addEventListener('click',e=>{const layout=e.target.closest('[data-layout]');if(layout){state.layout=layout.dataset.layout;render();return}const shortcut=e.target.closest('[data-search]');if(shortcut){state.query=shortcut.dataset.search;state.region='all';state.condition='all';$('#search').value=state.query;$('#condition').value='all';render();$('#results-section').scrollIntoView({block:'start',behavior:'smooth'});return}const detail=e.target.closest('[data-detail]');if(detail){openDetail(detail.dataset.detail,detail.dataset.focus);return}const quick=e.target.closest('[data-quick]');if(quick){const p=plans.find(p=>p.faqs.some(f=>f.id===quick.dataset.quick));openDetail(p.id,quick.dataset.quick);return}const close=e.target.closest('[data-close]');if(close){document.getElementById(close.dataset.close).close();return}const region=e.target.closest('[data-region]');if(region){state.region=region.dataset.region;if(state.view!=='plans')location.hash='plans';else render();return}const filter=e.target.closest('[data-filter]');if(filter){state.region=filter.dataset.filter;render();return}if(e.target.closest('#reset-filters')){state.region='all';state.condition='all';state.query='';$('#search').value='';$('#condition').value='all';render()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-compare]'))toggleCompare(e.target.dataset.compare,e.target.checked)});
$('#search').addEventListener('input',e=>{state.query=e.target.value;render()});$('#condition').addEventListener('change',e=>{state.condition=e.target.value;render()});$('#clear-compare').addEventListener('click',()=>{state.selected.clear();render()});$('#open-compare').addEventListener('click',openCompare);
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
function syncView(){const view=location.hash.slice(1);state.view=['plans','requirements','faq','sources'].includes(view)?view:'plans';render()}
window.addEventListener('hashchange',syncView);
$('#country-nav').innerHTML=countries.map(c=>`<button data-region="${c.id}"><span class="country-mini">${c.id}</span>${c.name}<span>${c.dial}</span></button>`).join('');
$('#country-select').innerHTML='<option value="all">选择国家 / 地区</option>'+countries.map(c=>`<option value="${c.id}">${c.name} ${c.dial}</option>`).join('');
$('#country-select').addEventListener('change',e=>{state.region=e.target.value;render()});
hydrateIcons();const count=plans.reduce((n,p)=>n+p.faqs.length,0);$('#faq-total').textContent=count;$('#faq-nav-count').textContent=count;$('#plan-total').textContent=plans.length;$('#plan-nav-count').textContent=plans.length;$('#country-total').textContent=countries.length;syncView();
